author: Johannes Faber (FAI-Solutions)
website: https://FAI-Solutions.github.io
open-webui_extension_hub: https://github.com/FAI-Solutions/open-webui-extensions
openwebui_id: 8b79ffd1-640d-4b43-b816-cc0071eb4e3b
description: Shows Ollama Cloud usage stats as an embed above each LLM response. Detailed setup in github-repo: https://github.com/FAI-Solutions/open-webui-extensions/tree/main/ollama-usage-monitor
requirements: cloudscraper, beautifulsoup4
version: 1.1
"""

import asyncio
import json
import re
import time
import html as html_mod
from typing import Optional, Callable, Dict, List
from dataclasses import dataclass, field
from pydantic import BaseModel, Field
import cloudscraper


# Data classes for parsed usage
@dataclass
class ModelUsage:
    """A single model's usage or aggregated request count."""

    name: str
    requests: str = ""
    extra: str = ""


@dataclass
class RecentRequest:
    """A single entry from the 'Recent requests' table."""

    time_ago: str
    timestamp: str
    model: str
    cost: str


@dataclass
class UsageMeter:
    """A single usage progress bar (e.g., Free usage, Session usage, Weekly usage)."""

    label: str
    percent: str
    reset_text: str = ""
    reset_iso: str = ""
    models: List[ModelUsage] = field(default_factory=list)


@dataclass
class UsageData:
    """Parsed usage data from Ollama Cloud Settings."""

    plan: str = ""
    balance: str = ""
    auto_reload: str = ""
    meters: List[UsageMeter] = field(default_factory=list)
    weekly_models: List[ModelUsage] = field(default_factory=list)
    recent_requests: List[RecentRequest] = field(default_factory=list)
    # Legacy compatibility fields
    session_percent: str = "N/A"
    session_reset: str = "N/A"
    weekly_percent: str = "N/A"
    weekly_reset: str = "N/A"
    error_message: str = ""

    def format_compact(self) -> str:
        """Format usage data in compact form for the summary header."""
        if self.error_message:
            return f"Error: {self.error_message}"

        parts = []

        # 1. Format all detected usage meters
        for m in self.meters:
            short_label = (
                m.label.replace(" usage", "")
                .replace("Usage", "")
                .strip()
                or "Usage"
            )
            pct = m.percent.replace(" used", "").strip()
            rst = (
                m.reset_text.replace("Resets in ", "")
                .replace("Refills in ", "")
                .rstrip(".")
                .strip()
            )
            if rst:
                parts.append(f"{short_label} {pct} → Reset {rst}")
            else:
                parts.append(f"{short_label} {pct}")

        # 2. Fallback to legacy fields if no meters list was populated
        if not parts and (
            self.session_percent != "N/A" or self.weekly_percent != "N/A"
        ):
            weekly_pct = self.weekly_percent.replace(" used", "")
            session_pct = self.session_percent.replace(" used", "")
            weekly_reset = (
                self.weekly_reset.replace("Resets in ", "")
                .replace("Refills in ", "")
                .rstrip(".")
            )
            session_reset = (
                self.session_reset.replace("Resets in ", "")
                .replace("Refills in ", "")
                .rstrip(".")
            )
            parts.append(
                f"Weekly {weekly_pct} → Reset {weekly_reset} • "
                f"Session {session_pct} → Reset {session_reset}"
            )

        # 3. Append extra credits balance if present
        if self.balance:
            parts.append(f"Credits: {self.balance}")

        return " • ".join(parts) if parts else "No active usage meters found"


# Ollama usage client (cloudscraper-based)
class OllamaUsageClient:
    """Fetches Ollama Cloud usage stats via cloudscraper, bypassing Cloudflare."""

    BASE_URL = "https://ollama.com/settings"

    def __init__(
        self,
        name: str = "",
        secure_session: str = "",
        aid: str = "",
        cf_clearance: Optional[str] = None,
        debug: bool = False,
    ):
        self.name = name
        self.secure_session = secure_session
        self.aid = aid
        self.cf_clearance = cf_clearance
        self.debug = debug

        self.scraper = cloudscraper.create_scraper()
        self._setup_cookies()

    def _log(self, msg: str):
        """Print debug message if debug mode is enabled."""
        if self.debug:
            print(f"DEBUG [client:{self.name}]: {msg}")

    def _setup_cookies(self):
        """Configure cookies for the session."""
        cookies = {
            "__Secure-session": self.secure_session,
        }
        if self.aid:
            cookies["aid"] = self.aid
        if self.cf_clearance:
            cookies["cf_clearance"] = self.cf_clearance

        if hasattr(self.scraper, "cookies"):
            self.scraper.cookies.update(cookies)

    def fetch_usage(self) -> UsageData:
        """Fetch usage data from the Ollama settings page."""
        start = time.monotonic()
        try:
            headers = {
                "User-Agent": (
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) "
                    "Chrome/128.0.0.0 Safari/537.36"
                ),
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            }

            response = self.scraper.get(
                self.BASE_URL, headers=headers, timeout=15, allow_redirects=True
            )
            response.raise_for_status()

            self._log(f"Response status: {response.status_code}, URL: {response.url}")

            # Check if redirected to sign-in page (expired or invalid cookies)
            if "/signin" in str(response.url) or "/login" in str(response.url):
                self._log("Redirected to signin — session cookie expired or invalid")
                return UsageData(
                    error_message="Session expired or invalid (redirected to sign-in). Please update cookies."
                )

            # Check for Cloudflare challenge page
            if (
                "Just a moment" in response.text
                or "cf-browser-verification" in response.text
            ):
                self._log("Cloudflare challenge detected")
                return UsageData(
                    error_message="Cloudflare challenge still active - need fresh cf_clearance"
                )

            data = self._parse_html(response.text)
            self._log(f"Fetch completed in {time.monotonic() - start:.2f}s")
            return data

        except Exception as e:
            self._log(
                f"Fetch error after {time.monotonic() - start:.2f}s: "
                f"{type(e).__name__}: {str(e)[:100]}"
            )
            return UsageData(
                error_message=f"Fetch error: {type(e).__name__}: {str(e)[:50]}"
            )

    def _parse_html(self, html: str) -> UsageData:
        """Extract usage data from the settings page HTML (supports new & legacy layouts)."""
        try:
            from bs4 import BeautifulSoup
        except ImportError:
            return UsageData(error_message="BeautifulSoup not available")

        soup = BeautifulSoup(html, "html.parser")
        data = UsageData()

        all_h2 = [h.get_text(" ", strip=True) for h in soup.find_all("h2")]
        self._log(f"All h2 tags: {all_h2}")

        # Verify we are actually on the authenticated usage settings page
        has_extra_usage = soup.find(id="extra-usage") is not None
        has_usage_meter = soup.find(attrs={"data-usage-meter": True}) is not None
        has_recent_reqs = soup.find(id="recent-requests-self") is not None
        has_legacy_h2 = any("Cloud usage" in h for h in all_h2)
        has_new_h2 = any(
            "Usage credits" in h or "Usage breakdown" in h for h in all_h2
        )

        if not (
            has_extra_usage
            or has_usage_meter
            or has_recent_reqs
            or has_legacy_h2
            or has_new_h2
        ):
            page_title = soup.title.get_text(strip=True) if soup.title else "No title"
            self._log(f"Usage markers NOT found. Page title: {page_title}")
            if "Sign in" in page_title or soup.find("form", action="/signin"):
                return UsageData(
                    error_message="Not signed in — please refresh __Secure-session and aid cookies"
                )
            return UsageData(
                error_message=f"Usage section not found on page (Title: {page_title})"
            )

        # 1. Parse Plan Badge & Extra Usage Credits Balance
        extra_usage_div = soup.find(id="extra-usage")
        if extra_usage_div:
            h2 = extra_usage_div.find("h2")
            if h2:
                badge = h2.find("span")
                if badge:
                    data.plan = badge.get_text(strip=True).lower()
            balance_el = soup.find(id="extra-usage-balance")
            if balance_el:
                data.balance = balance_el.get_text(strip=True)
            reload_el = soup.find(id="extra-usage-auto-reload-summary")
            if reload_el:
                data.auto_reload = reload_el.get_text(strip=True)

        # Fallback plan detection if #extra-usage badge wasn't found
        if not data.plan:
            for h2 in soup.find_all("h2"):
                span = h2.find("span")
                if span:
                    txt = span.get_text(strip=True).lower()
                    if txt in ("free", "pro", "max", "team", "enterprise"):
                        data.plan = txt
                        break
            if not data.plan and soup.find(id="free-plan-models"):
                data.plan = "free"

        self._log(
            f"Detected plan='{data.plan}', balance='{data.balance}', auto_reload='{data.auto_reload}'"
        )

        # 2. Parse Usage Meters
        meter_divs = soup.find_all(attrs={"data-usage-meter": True})
        self._log(f"Found {len(meter_divs)} data-usage-meter element(s)")

        for meter_div in meter_divs:
            container = meter_div.parent
            label = ""
            percent = ""
            reset_text = ""
            reset_iso = ""

            if container:
                # Header row above meter: <div class="flex justify-between mb-2">
                header_div = container.find(
                    "div",
                    class_=lambda c: c and "flex" in c and "justify-between" in c,
                )
                if header_div:
                    spans = header_div.find_all("span")
                    if len(spans) >= 2:
                        label = spans[0].get_text(strip=True)
                        percent = spans[1].get_text(strip=True)

                # Reset/Refill time below meter: <div class="... local-time" data-time="...">
                time_div = container.find(
                    "div", class_=lambda c: c and "local-time" in c
                )
                if time_div:
                    reset_text = time_div.get_text(strip=True)
                    reset_iso = time_div.get("data-time", "")

            # Fallback to aria-label on data-usage-track if header spans weren't found
            track = meter_div.find(attrs={"data-usage-track": True})
            if track and (not label or not percent):
                aria = track.get("aria-label", "")
                if ":" in aria:
                    parts = aria.split(":", 1)
                    label = label or parts[0].strip()
                    percent = percent or parts[1].strip()

            # Parse any per-model segments inside the meter bar (data-usage-segment)
            seg_models: List[ModelUsage] = []
            pct_match = re.search(r"([\d.]+)", percent)
            overall_pct = float(pct_match.group(1)) if pct_match else 0.0

            for seg in meter_div.find_all(attrs={"data-usage-segment": True}):
                m_name = seg.get("data-model", "").strip()
                m_reqs = seg.get("data-requests", "").strip()
                style = seg.get("style", "")
                w_match = re.search(r"width:\s*([\d.]+)%", style)
                seg_extra = ""
                if w_match and overall_pct > 0:
                    contrib = (float(w_match.group(1)) / 100.0) * overall_pct
                    seg_extra = f"{contrib:.1f}%"
                if m_name:
                    req_label = (
                        f"{m_reqs} req"
                        if m_reqs == "1"
                        else f"{m_reqs} reqs"
                        if m_reqs
                        else ""
                    )
                    seg_models.append(
                        ModelUsage(name=m_name, requests=req_label, extra=seg_extra)
                    )

            if label or percent:
                meter_obj = UsageMeter(
                    label=label or "Usage",
                    percent=percent or "N/A",
                    reset_text=reset_text,
                    reset_iso=reset_iso,
                    models=seg_models,
                )
                data.meters.append(meter_obj)
                self._log(
                    f"Parsed meter: label='{meter_obj.label}', "
                    f"percent='{meter_obj.percent}', reset='{meter_obj.reset_text}', "
                    f"segments={len(seg_models)}"
                )

                # Populate legacy fields if applicable
                lbl_low = meter_obj.label.lower()
                if "session" in lbl_low:
                    data.session_percent = meter_obj.percent
                    data.session_reset = meter_obj.reset_text or "N/A"
                elif "weekly" in lbl_low:
                    data.weekly_percent = meter_obj.percent
                    data.weekly_reset = meter_obj.reset_text or "N/A"

        # Fallback if a page has `div.flex.justify-between.mb-2` without `data-usage-meter`
        if not data.meters:
            usage_divs = soup.find_all("div", class_="flex justify-between mb-2")
            time_divs = [
                d
                for d in soup.find_all("div", class_="local-time")
                if not d.find_parent(id="recent-requests-self")
            ]
            for idx, div in enumerate(usage_divs):
                spans = div.find_all("span")
                if len(spans) >= 2:
                    lbl = spans[0].get_text(strip=True)
                    val = spans[1].get_text(strip=True)
                    rst = (
                        time_divs[idx].get_text(strip=True)
                        if idx < len(time_divs)
                        else ""
                    )
                    data.meters.append(
                        UsageMeter(label=lbl, percent=val, reset_text=rst)
                    )

        # 3. Parse Legacy Weekly Models (#weekly-usage-models) if present
        models_container = soup.find("div", id="weekly-usage-models")
        if models_container:
            for row in models_container.find_all(
                "div",
                class_=lambda c: c
                and "flex" in c
                and "min-w-0" in c
                and "items-center" in c
                and "gap-2" in c,
            ):
                spans = row.find_all("span")
                if len(spans) < 3:
                    continue
                name = spans[1].get("title") or spans[1].get_text(strip=True)
                requests = spans[2].get_text(strip=True)
                if name:
                    data.weekly_models.append(ModelUsage(name=name, requests=requests))
                    self._log(f"Weekly model: '{name}' -> {requests}")

        # If weekly_models wasn't populated from #weekly-usage-models, check meter segments
        if not data.weekly_models:
            for m in data.meters:
                if m.models:
                    data.weekly_models.extend(m.models)

        # 4. Parse New "Recent requests" Table
        recent_sec = soup.find(id="recent-requests-self")
        if recent_sec:
            rows = recent_sec.find_all("tr")
            self._log(f"Found {len(rows)} rows in #recent-requests-self")
            for tr in rows:
                tds = tr.find_all("td")
                if len(tds) >= 3:
                    time_ago = tds[0].get_text(strip=True)
                    timestamp = tds[0].get("data-time", "")
                    model_div = tds[1].find("div")
                    model_name = (
                        (model_div.get("title") or model_div.get_text(strip=True))
                        if model_div
                        else tds[1].get_text(strip=True)
                    )
                    cost = tds[2].get_text(strip=True)
                    if model_name:
                        data.recent_requests.append(
                            RecentRequest(
                                time_ago=time_ago,
                                timestamp=timestamp,
                                model=model_name,
                                cost=cost,
                            )
                        )

        self._log(f"Parsed summary: {data.format_compact()}")
        return data


# Embed HTML builder
def _esc(text) -> str:
    return html_mod.escape(str(text), quote=True)


def _aggregate_recent_models(recent_requests: List[RecentRequest]) -> List[ModelUsage]:
    """Aggregate recent request rows by model name for a clean summary table."""
    counts: Dict[str, int] = {}
    costs: Dict[str, float] = {}
    all_included: Dict[str, bool] = {}

    for r in recent_requests:
        counts[r.model] = counts.get(r.model, 0) + 1
        if r.model not in all_included:
            all_included[r.model] = True
        cost_str = r.cost.strip()
        if cost_str.lower() != "included":
            all_included[r.model] = False
            m = re.search(r"([\d.]+)", cost_str.replace(",", ""))
            if m:
                costs[r.model] = costs.get(r.model, 0.0) + float(m.group(1))

    result: List[ModelUsage] = []
    for model, count in counts.items():
        req_str = "1 request" if count == 1 else f"{count} requests"
        if all_included.get(model, True):
            extra_str = "Included"
        elif model in costs:
            extra_str = f"${costs[model]:.2f}"
        else:
            extra_str = ""
        result.append(ModelUsage(name=model, requests=req_str, extra=extra_str))
    return result


def _build_embed(accounts: List[Dict]) -> str:
    """Build the sandboxed iframe card. `accounts` is a list of dicts with
    keys: name, data (UsageData). Renders one expandable row per account."""

    rows = ""
    for acc in accounts:
        name = _esc(acc["name"])
        d: UsageData = acc["data"]

        if d.error_message:
            rows += (
                f'<details class="acc"><summary>'
                f'<span class="an">{name}</span>'
                f'<span class="as err">{_esc(d.error_message)}</span>'
                f"</summary></details>\n"
            )
            continue

        plan_badge = (
            f'<span class="badge badge-{_esc(d.plan)}">{_esc(d.plan.upper())}</span>'
            if d.plan
            else ""
        )
        stats = _esc(d.format_compact())

        body_sections = ""

        # Section A: Extra Usage Credits & Auto-reload info (if available)
        if d.balance or d.auto_reload:
            bal_text = _esc(d.balance or "$0")
            reload_text = (
                f" (Auto-reload: {_esc(d.auto_reload)})" if d.auto_reload else ""
            )
            body_sections += (
                f'<div class="mhead">Usage Credits</div>'
                f'<div class="mrow"><span class="mname">Pay-as-you-go balance{reload_text}</span>'
                f'<span class="mreq">{bal_text}</span></div>'
            )

        # Section B: Weekly / Meter Model Breakdown (if available)
        if d.weekly_models:
            model_rows = "".join(
                f'<div class="mrow"><span class="mname">{_esc(m.name)}</span>'
                f'<span class="mreq">{_esc(m.requests)}'
                f'{f" ({_esc(m.extra)})" if m.extra else ""}</span></div>'
                for m in d.weekly_models
            )
            body_sections += (
                f'<div class="mhead">Models used</div>{model_rows}'
            )

        # Section C: Recent Requests (if available)
        if d.recent_requests:
            if not d.weekly_models:
                agg_models = _aggregate_recent_models(d.recent_requests)
                agg_rows = "".join(
                    f'<div class="mrow"><span class="mname">{_esc(m.name)}</span>'
                    f'<span class="mreq">{_esc(m.requests)}'
                    f'{f" · {_esc(m.extra)}" if m.extra else ""}</span></div>'
                    for m in agg_models
                )
                body_sections += (
                    f'<div class="mhead">Recent models summary ({len(d.recent_requests)} shown)</div>'
                    f"{agg_rows}"
                )

            req_rows = "".join(
                f'<div class="mrow"><span class="mname">{_esc(r.model)} '
                f'<small class="dim">({_esc(r.time_ago)})</small></span>'
                f'<span class="mreq">{_esc(r.cost)}</span></div>'
                for r in d.recent_requests[:8]
            )
            body_sections += (
                f'<div class="mhead">Latest requests</div>{req_rows}'
            )

        if not d.weekly_models and not d.recent_requests:
            body_sections += (
                '<div class="mhead">Activity</div>'
                '<div class="mrow"><span class="mname dim">No model requests recorded recently</span></div>'
            )

        rows += (
            f'<details class="acc"><summary>'
            f'<span class="an">{name}</span>'
            f"{plan_badge}"
            f'<span class="as">{stats}</span>'
            f"</summary>"
            f'<div class="abody">'
            f"{body_sections}"
            f"</div></details>\n"
        )

    return f"""<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
*{{box-sizing:border-box;margin:0;padding:0}}
body{{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;font-size:13px;background:#0f1117;color:#e4e6eb;line-height:1.45}}
@media(prefers-color-scheme:light){{body{{background:#f5f6fa;color:#1a1d27}}}}
#app{{padding:10px 14px}}
.hdr{{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:8px}}
.hdr .t{{font-size:11px;font-weight:700;color:#6c8cff}}
.hdr .t small{{font-weight:400;color:#a0a4b0;font-size:.85em}}
.hdr a{{font-size:10px;color:#6c8cff;text-decoration:none}}
.hdr a:hover{{text-decoration:underline}}
details.acc{{background:#1a1d27;border:1px solid #252830;border-radius:8px;margin-bottom:6px;overflow:hidden}}
@media(prefers-color-scheme:light){{details.acc{{background:#fff;border-color:#ecedf1}}}}
details.acc>summary{{cursor:pointer;list-style:none;display:flex;align-items:center;gap:8px;padding:8px 12px;user-select:none;flex-wrap:wrap}}
details.acc>summary::-webkit-details-marker{{display:none}}
details.acc>summary::before{{content:'▸';color:#6c8cff;transition:transform .15s;flex:none}}
details.acc[open]>summary::before{{transform:rotate(90deg)}}
details.acc>summary:hover{{background:#252830}}
@media(prefers-color-scheme:light){{details.acc>summary:hover{{background:#ecedf1}}}}
.an{{font-weight:600;flex:none}}
.badge{{font-size:10px;font-weight:700;padding:1px 6px;border-radius:999px;background:#252830;color:#a0a4b0;flex:none;letter-spacing:.03em}}
.badge-pro,.badge-max,.badge-team{{background:rgba(108,140,255,0.18);color:#6c8cff}}
@media(prefers-color-scheme:light){{.badge{{background:#ecedf1;color:#555}}.badge-pro,.badge-max,.badge-team{{background:rgba(108,140,255,0.15);color:#3b5bdb}}}}
.as{{color:#a0a4b0;font-size:12px;word-break:break-word}}
.as.err{{color:#ff6b6b}}
